'use strict';
// dial: a number goes through the steps named on the way and comes out as
// text, with the unit of its scale.
//
//   dial.double.floor(2.75)                              "5"
//   new dial.Scale({unit: 'kg', places: 1}).half(3)      "1.5 kg"
//
// Every dial is a function. Its steps are accessors on one object all
// dials inherit from: reading a step makes the next dial and remembers it
// on the dial it was read from. A scale is made by a class whose
// constructor answers a dial.

const steps = {
	half: (amount) => amount / 2,
	double: (amount) => amount * 2,
	negate: (amount) => -amount,
	floor: (amount) => Math.floor(amount),
};

function dialOf(scale, run) {
	const dial = (amount) => {
		let value = amount;
		for (const step of run) {
			value = step(value);
		}
		const text = scale.places === undefined ? String(value) : value.toFixed(scale.places);
		return scale.unit === '' ? text : text + ' ' + scale.unit;
	};
	Object.setPrototypeOf(dial, shared);
	dial.scale = scale;
	dial.run = run;
	return dial;
}

const accessors = {
	unit: {
		enumerable: true,
		get() {
			return this.scale.unit;
		},
	},
};
for (const name of Object.keys(steps)) {
	accessors[name] = {
		get() {
			const next = dialOf(this.scale, [...this.run, steps[name]]);
			Object.defineProperty(this, name, {value: next});
			return next;
		},
	};
}

// What every dial inherits from: a function itself, so a dial stays one.
const shared = Object.defineProperties(function dial() {}, accessors);

class Scale {
	constructor(options) {
		const given = options === undefined ? {} : options;
		// eslint-disable-next-line no-constructor-return
		return dialOf({unit: given.unit === undefined ? '' : given.unit, places: given.places}, []);
	}
}

// A dial's steps come from the object it inherits from, which the types
// read from this file do not show: the exported dial is untyped here, and
// index.d.ts says what it has.
/** @type {any} */
const bare = dialOf({unit: '', places: undefined}, []);
bare.Scale = Scale;
module.exports = bare;
